scene.add(new THREE.AmbientLight(0xffffff, 0.86));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.75);
keyLight.position.set(-2, 4, 5);
scene.add(keyLight);

const matWire = new THREE.MeshPhongMaterial({ color: 0x9b9b9b, shininess: 70 });
const matHi = new THREE.MeshBasicMaterial({ color: 0xd9d9d9 });
const matShadow = new THREE.MeshBasicMaterial({ color: 0x666666 });
const matSkin = new THREE.MeshPhongMaterial({ color: 0xf0c998, shininess: 18 });
const matSkin2 = new THREE.MeshPhongMaterial({ color: 0xe7bb83, shininess: 12 });
const matSkinShadow = new THREE.MeshPhongMaterial({ color: 0xd9a96f, shininess: 10 });
const matOutline = new THREE.LineBasicMaterial({ color: 0xc58e55 });
const matNail = new THREE.MeshPhongMaterial({ color: 0xf5dfc5, shininess: 30 });
const matBlue = new THREE.MeshBasicMaterial({ color: 0x008bd2 });
const matCyan = new THREE.MeshBasicMaterial({ color: 0x00a8ff });
const matRed = new THREE.MeshBasicMaterial({ color: 0xd93333 });

function cylBetween(a, b, radius, material, radialSegments = 16) {
  const va = new THREE.Vector3(a[0], a[1], a[2]);
  const vb = new THREE.Vector3(b[0], b[1], b[2]);
  const dir = vb.clone().sub(va);
  const len = dir.length();
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, len, radialSegments), material);
  mesh.position.copy(va).add(vb).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  return mesh;
}

function ellipsoid(x, y, z, sx, sy, sz, material, seg = 32) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(1, seg, Math.max(12, seg / 2)), material);
  m.position.set(x, y, z);
  m.scale.set(sx, sy, sz);
  return m;
}

function lineCurve(points, material = matOutline) {
  const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(p[0], p[1], p[2])));
  const pts = curve.getPoints(40);
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), material);
}

const wireGroup = new THREE.Group();
wireGroup.add(cylBetween([-5.8, 0, 0], [5.8, 0, 0], 0.055, matWire, 32));
wireGroup.add(cylBetween([-5.8, 0.046, 0.018], [5.8, 0.046, 0.018], 0.011, matHi, 12));
wireGroup.add(cylBetween([-5.8, -0.043, 0.025], [5.8, -0.043, 0.025], 0.014, matShadow, 12));
