hand.add(ellipsoid(-4.15, -1.20, 0.10, 0.55, 0.46, 0.18, matSkin2));
hand.add(ellipsoid(-3.85, -0.55, 0.13, 0.93, 0.78, 0.25, matSkin));
hand.add(ellipsoid(-4.48, -0.35, 0.14, 0.34, 0.58, 0.18, matSkinShadow));
hand.add(ellipsoid(-3.25, -0.20, 0.17, 0.42, 0.45, 0.18, matSkin));

const fingerXs = [-4.48, -4.08, -3.68, -3.27];
const fingerHeights = [0.80, 0.90, 0.86, 0.72];
for (let i = 0; i < 4; i++) {
  const x = fingerXs[i];
  const y = fingerHeights[i];
  hand.add(ellipsoid(x, y, 0.18, 0.20, 0.34, 0.16, matSkin));
  hand.add(ellipsoid(x + 0.05, y - 0.32, 0.22, 0.23, 0.26, 0.16, matSkin2));
  hand.add(ellipsoid(x + 0.08, y - 0.13, 0.40, 0.115, 0.085, 0.024, matNail, 24));
  hand.add(lineCurve([[x - 0.11, y - 0.27, 0.42], [x + 0.03, y - 0.34, 0.43], [x + 0.16, y - 0.28, 0.42]]));
}
hand.add(ellipsoid(-4.76, 0.25, 0.11, 0.25, 0.44, 0.14, matSkinShadow));
hand.add(ellipsoid(-2.92, 0.12, 0.15, 0.24, 0.28, 0.13, matSkin));

const thumbRight = new THREE.Group();
thumbRight.add(ellipsoid(-2.72, -0.48, 0.20, 0.45, 0.25, 0.16, matSkin));
thumbRight.add(ellipsoid(-2.13, -0.55, 0.20, 0.55, 0.22, 0.15, matSkin));
thumbRight.add(ellipsoid(-1.68, -0.54, 0.20, 0.24, 0.18, 0.14, matSkin));
thumbRight.add(lineCurve([[-2.65, -0.25, 0.43], [-2.25, -0.35, 0.44], [-1.90, -0.47, 0.43]]));
hand.add(thumbRight);

const thumbLeft = new THREE.Group();
thumbLeft.add(ellipsoid(-4.50, -0.45, 0.20, 0.45, 0.25, 0.16, matSkin));
thumbLeft.add(ellipsoid(-5.05, -0.54, 0.20, 0.52, 0.21, 0.15, matSkin));
thumbLeft.add(ellipsoid(-5.45, -0.55, 0.20, 0.23, 0.17, 0.14, matSkin));
thumbLeft.add(lineCurve([[-4.55, -0.25, 0.43], [-4.95, -0.35, 0.44], [-5.28, -0.47, 0.43]]));
hand.add(thumbLeft);

hand.add(lineCurve([[-4.55, -0.92, 0.42], [-4.15, -0.55, 0.44], [-3.55, -0.63, 0.43], [-3.04, -0.28, 0.42]]));
hand.add(lineCurve([[-4.40, -1.05, 0.41], [-4.02, -0.92, 0.43], [-3.68, -0.98, 0.42]]));
hand.add(lineCurve([[-4.67, -0.10, 0.42], [-4.26, -0.03, 0.44], [-3.90, -0.14, 0.43]]));
hand.add(lineCurve([[-3.72, -0.18, 0.43], [-3.30, -0.02, 0.43], [-2.94, -0.08, 0.42]]));

const currentArrow = new THREE.Group();
scene.add(currentArrow);

function rebuildCurrentArrow(dirRight) {
  while (currentArrow.children.length) {
    const ch = currentArrow.children.pop();
    ch.geometry?.dispose?.();
  }
  const y = -0.28, z = 0.18;
  const start = dirRight ? [-1.65, y, z] : [-0.85, y, z];
  const end = dirRight ? [-0.96, y, z] : [-1.54, y, z];
  const tip = dirRight ? [-0.85, y, z] : [-1.65, y, z];
  currentArrow.add(cylBetween(start, end, 0.012, matRed, 10));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.16, 20), matRed);
  cone.position.set(tip[0], tip[1], tip[2]);
  const dir = new THREE.Vector3(dirRight ? 1 : -1, 0, 0);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  currentArrow.add(cone);
}

const loopCenters = [0.0, 1.25, 2.5, 3.75];
const fixedRadii = [0.28, 0.47, 0.72, 1.05, 1.45];
const loopArrowData = [];
const arrowGeo = new THREE.ConeGeometry(0.052, 0.15, 18);

function circleTube(x, r, material, tubeRadius) {
  const pts = [];
  const n = 144;
  for (let i = 0; i <= n; i++) {
    const t = i / n * Math.PI * 2;
    pts.push(new THREE.Vector3(x, r * Math.cos(t), r * Math.sin(t)));
  }
  const curve = new THREE.CatmullRomCurve3(pts, true);
  return new THREE.Mesh(new THREE.TubeGeometry(curve, 144, tubeRadius, 8, true), material);
}

const loopGroup = new THREE.Group();
scene.add(loopGroup);
for (const x of loopCenters) {
  for (const r of fixedRadii) {
    const loop = circleTube(x, r, matBlue, 0.012);
    loopGroup.add(loop);
    const theta = THREE.MathUtils.degToRad(140);
    const arrow = new THREE.Mesh(arrowGeo, matBlue);
    arrow.position.set(x, r * Math.cos(theta), r * Math.sin(theta));
    loopGroup.add(arrow);
    loopArrowData.push({ mesh: arrow, x, r, theta });
  }
}

let selectedLoopGroup = new THREE.Group();
scene.add(selectedLoopGroup);
let radialGroup = new THREE.Group();
scene.add(radialGroup);
let markerDot = null;
let markerHit = null;
let currentDirRight = true;
let currentRadius = 0.8;

function orientLoopArrow(entry) {
  const s = currentDirRight ? 1 : -1;
  const t = entry.theta;
  const tangent = new THREE.Vector3(0, -Math.sin(t), Math.cos(t)).multiplyScalar(s).normalize();
  entry.mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
}

function updateDirection(dirText) {
  currentDirRight = dirText === 'I right';
  thumbRight.visible = currentDirRight;
  thumbLeft.visible = !currentDirRight;
  rebuildCurrentArrow(currentDirRight);
  for (const a of loopArrowData) orientLoopArrow(a);
}

function disposeChildren(g) {
  while (g.children.length) {
    const ch = g.children.pop();
    ch.geometry?.dispose?.();
    if (ch.children?.length) disposeChildren(ch);
  }
}

function rebuildSelectedRadius(r) {
  disposeChildren(selectedLoopGroup);
  for (const x of loopCenters) {
    selectedLoopGroup.add(circleTube(x, r, matCyan, x === 3.75 ? 0.025 : 0.019));
  }

  disposeChildren(radialGroup);
  const x = 3.75;
  radialGroup.add(cylBetween([x, 0, 0], [x, r, 0], 0.014, matCyan, 12));
  markerDot = ellipsoid(x, r, 0, 0.08, 0.08, 0.08, matCyan, 24);
  markerHit = ellipsoid(x, r, 0, 0.18, 0.18, 0.18, new THREE.MeshBasicMaterial({ color: 0x00a8ff, transparent: true, opacity: 0.0 }), 16);
  radialGroup.add(markerDot);
  radialGroup.add(markerHit);
  registerInteractive(markerHit, {
    title: 'Distance from the wire',
    tooltip: 'Drag the cyan dot or use the slider',
    body: 'The field around a straight current-carrying wire decreases with distance: B is proportional to 1/r.'
  });
}

function fieldStrength(r) {
  return 0.35 / r;
}

function updateRadius(r) {
  currentRadius = Math.max(0.35, Math.min(2, Number(r)));
  rebuildSelectedRadius(currentRadius);
  const b = fieldStrength(currentRadius);
  const slider = document.getElementById('distanceFromWire');
  if (slider) slider.value = currentRadius.toFixed(2);
  const rr = document.getElementById('rReadout');
  if (rr) rr.textContent = `r = ${currentRadius.toFixed(2)}, B/B0 = ${b.toFixed(2)}`;
  if (bLabel) {
    bLabel.pos.set(4.45, currentRadius + 0.22, 0.05);
    bLabel.div.innerHTML = `B/B<sub>0</sub> = ${b.toFixed(2)}`;
  }
}

updateDirection('I right');
rebuildSelectedRadius(currentRadius);

setCameraView({
  projection: 'perspective',
  azimuthDeg: 35,
  elevationDeg: 5,
  rollDeg: 0,
  heightFraction: 0.62
});

