  hand.add(ellipsoid(x + 0.07, fingerTop[i] - 0.26, 0.33, 0.23 * k, 0.25 * k, 0.16, matSkin));
  hand.add(ellipsoid(x + 0.10, fingerTop[i] - 0.10, 0.50, 0.105 * k, 0.080 * k, 0.020, matNail, 24));
  hand.add(lineCurve([[x - 0.12, fingerTop[i] - 0.25, 0.53], [x + 0.03, fingerTop[i] - 0.32, 0.54], [x + 0.16, fingerTop[i] - 0.26, 0.53]], matOutline, 24));
}

const thumbRight = new THREE.Group();
thumbRight.add(ellipsoid(-2.80, -0.42, 0.30, 0.38, 0.30, 0.15, matSkin));
thumbRight.add(cylBetween([-2.72, -0.47, 0.30], [-2.05, -0.52, 0.30], 0.18, matSkin, 24));
thumbRight.add(ellipsoid(-2.02, -0.53, 0.30, 0.34, 0.20, 0.14, matSkin));
thumbRight.add(ellipsoid(-1.68, -0.54, 0.30, 0.22, 0.16, 0.12, matSkin));
thumbRight.add(ellipsoid(-1.62, -0.47, 0.46, 0.090, 0.050, 0.018, matNail, 20));
thumbRight.add(lineCurve([[-2.70, -0.20, 0.52], [-2.35, -0.34, 0.54], [-1.92, -0.45, 0.53], [-1.68, -0.44, 0.50]], matOutline, 36));
hand.add(thumbRight);

const thumbLeft = new THREE.Group();
