thumbLeft.add(cylBetween([-4.55, -0.48, 0.30], [-5.13, -0.53, 0.30], 0.18, matSkin, 24));
thumbLeft.add(ellipsoid(-5.15, -0.54, 0.30, 0.32, 0.20, 0.14, matSkin));
thumbLeft.add(ellipsoid(-5.47, -0.55, 0.30, 0.22, 0.16, 0.12, matSkin));
thumbLeft.add(ellipsoid(-5.53, -0.48, 0.46, 0.090, 0.050, 0.018, matNail, 20));
thumbLeft.add(lineCurve([[-4.55, -0.20, 0.52], [-4.88, -0.34, 0.54], [-5.25, -0.45, 0.53], [-5.48, -0.44, 0.50]], matOutline, 36));
