hand.add(lineCurve([[-4.36, -0.86, 0.52], [-4.00, -1.00, 0.53], [-3.55, -0.96, 0.52]], matOutline, 36));
hand.add(lineCurve([[-4.48, -0.05, 0.53], [-4.18, 0.08, 0.54], [-3.82, -0.03, 0.54]], matOutline, 32));
hand.add(lineCurve([[-3.72, -0.07, 0.54], [-3.35, 0.10, 0.54], [-3.00, 0.00, 0.53]], matOutline, 32));
registerInteractive(hand, {
  title: 'Right-hand rule',
  tooltip: 'Thumb = current, curled fingers = magnetic field',
  body: 'Point your right thumb along the current. The curl of the fingers gives the direction of the magnetic-field loops around the wire.'
});

const currentArrow = new THREE.Group();
scene.add(currentArrow);
let currentDirRight = true;

function rebuildCurrentArrow(dirRight) {
  while (currentArrow.children.length) {
    const ch = currentArrow.children.pop();
    disposeObject(ch);
  }
  const y = -0.28, z = 0.26;
  const tail = dirRight ? [-1.65, y, z] : [-0.85, y, z];
  const neck = dirRight ? [-0.98, y, z] : [-1.52, y, z];
  const tip = dirRight ? [-0.84, y, z] : [-1.66, y, z];
  currentArrow.add(cylBetween(tail, neck, 0.020, matRed, 16));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.20, 26), matRed);
  cone.position.set(tip[0], tip[1], tip[2]);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), new THREE.Vector3(dirRight ? 1 : -1, 0, 0));
  currentArrow.add(cone);
}

const loopCenters = [0.0, 1.25, 2.5, 3.75];
const loopRadii = [0.28, 0.47, 0.72, 1.05, 1.45];
const loopGroup = new THREE.Group();
scene.add(loopGroup);
const loopArrowData = [];

function circleTube(x, r, material, tubeRadius = 0.012) {
  const pts = [];
  const n = 160;
  for (let i = 0; i <= n; i++) {
    const t = (i / n) * Math.PI * 2;
    pts.push(new THREE.Vector3(x, r * Math.cos(t), r * Math.sin(t)));
  }
  const curve = new THREE.CatmullRomCurve3(pts, true);
  return new THREE.Mesh(new THREE.TubeGeometry(curve, 160, tubeRadius, 8, true), material);
}

for (const x of loopCenters) {
  for (const r of loopRadii) {
    const loop = circleTube(x, r, matBlue, 0.0115);
    loopGroup.add(loop);
    const theta = THREE.MathUtils.degToRad(140);
    const arrow = new THREE.Mesh(new THREE.ConeGeometry(r > 0.8 ? 0.060 : 0.047, r > 0.8 ? 0.17 : 0.13, 22), matBlue);
    arrow.position.set(x, r * Math.cos(theta), r * Math.sin(theta));
    loopGroup.add(arrow);
    loopArrowData.push({ mesh: arrow, x, r, theta });
  }
}
registerInteractive(loopGroup, {
  title: 'Magnetic-field loops',
  tooltip: 'Blue circles wrap around the wire',
  body: 'A long straight current produces circular magnetic-field lines centered on the wire. The loop arrows reverse if the current reverses.'
});

const selectedLoopGroup = new THREE.Group();
scene.add(selectedLoopGroup);
let selectedLoopMesh = null;

const radialGroup = new THREE.Group();
const radialLine = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.014, 1, 14), matCyan);
const markerDot = ellipsoid(3.75, 0.8, 0, 0.080, 0.080, 0.080, matCyan, 24);
const markerHit = ellipsoid(3.75, 0.8, 0, 0.22, 0.22, 0.22, new THREE.MeshBasicMaterial({ color: 0x00a8ff, transparent: true, opacity: 0.0 }), 16);
radialGroup.add(radialLine);
radialGroup.add(markerDot);
radialGroup.add(markerHit);
scene.add(radialGroup);
registerInteractive(markerHit, {
  title: 'Distance from the wire',
  tooltip: 'Drag the dot to change r',
  body: 'The magnetic-field strength around a straight wire is proportional to 1/r, so it is strongest close to the wire.'
});

let currentRadius = 0.8;
let bLabel = null;

function orientLoopArrow(entry) {
  const s = currentDirRight ? 1 : -1;
  const t = entry.theta;
  const tangent = new THREE.Vector3(0, -Math.sin(t), Math.cos(t)).multiplyScalar(s).normalize();
  entry.mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
}

function updateDirection(dirText) {
  currentDirRight = dirText === 'I right';
  thumbRight.visible = currentDirRight;
  thumbLeft.visible = !currentDirRight;
  rebuildCurrentArrow(currentDirRight);
  for (const a of loopArrowData) orientLoopArrow(a);
}

function fieldStrength(r) {
  return 0.35 / Math.max(0.35, r);
}

function updateSelectedLoop(r) {
  if (selectedLoopMesh) {
    selectedLoopGroup.remove(selectedLoopMesh);
    disposeObject(selectedLoopMesh);
  }
  selectedLoopMesh = circleTube(3.75, r, matCyanSoft, 0.024);
  selectedLoopGroup.add(selectedLoopMesh);
}

function updateRadius(r) {
  currentRadius = Math.max(0.35, Math.min(2.0, Number(r)));
  updateSelectedLoop(currentRadius);
  radialLine.position.set(3.75, currentRadius / 2, 0);
  radialLine.scale.set(1, currentRadius, 1);
  markerDot.position.set(3.75, currentRadius, 0);
  markerHit.position.set(3.75, currentRadius, 0);

  const slider = document.getElementById('distanceFromWire');
  if (slider) slider.value = currentRadius.toFixed(2);
  const b = fieldStrength(currentRadius);
  const rr = document.getElementById('rReadout');
  if (rr) rr.textContent = `r = ${currentRadius.toFixed(2)}, B/B0 = ${b.toFixed(2)}`;
  if (bLabel) {
    bLabel.pos.set(4.15, currentRadius + 0.18, 0.05);
    bLabel.div.innerHTML = `B/B<sub>0</sub> = ${b.toFixed(2)}`;
  }
}

updateDirection('I right');
updateRadius(currentRadius);

setCameraView({
  projection: 'perspective',
  azimuthDeg: 72,
  elevationDeg: 3,
  rollDeg: 0,
  heightFraction: 0.78,
  target: [0.0, 0.10, 0.0],
  distanceScale: 1.85
});

addLabel('<i>I</i>', new THREE.Vector3(-1.35, -0.58, 0.30), { fontSize: '20px', color: '#111' });
addLabel('<b>B&#8407;</b>', new THREE.Vector3(2.65, 1.72, 0.0), { fontSize: '22px', color: '#111', bold: true });
bLabel = addLabel(`B/B<sub>0</sub> = ${fieldStrength(currentRadius).toFixed(2)}`, new THREE.Vector3(4.15, currentRadius + 0.18, 0.05), {
  fontSize: '11px',
  color: '#006fa8',
  bold: true,
  background: 'rgba(255,255,255,0.72)'
});

document.getElementById('currentDirection').addEventListener('change', (e) => {
  updateDirection(e.target.value);
});
document.getElementById('distanceFromWire').addEventListener('input', (e) => {
  updateRadius(parseFloat(e.target.value));
});

const demoSteps = [
  {
    title: 'Rightward current',
    narration: 'The thumb points to the right along the wire, matching the red I arrow. The blue field arrows circulate in the same sense as the curled fingers.',
    state: { currentDirection: 'I right', distanceFromWire: 0.8 }
  },
  {
    title: 'Reverse the current',
    narration: 'When the current points left, the thumb flips left and every blue arrow reverses. This shows that reversing I reverses the magnetic-field circulation.',
    state: { currentDirection: 'I left', distanceFromWire: 0.8 }
  },
  {
    title: 'Move farther from the wire',
    narration: 'Drag the radial marker outward. The highlighted loop moves to a larger radius and the B readout falls, showing the field weakening with distance.',
    state: { currentDirection: 'I right', distanceFromWire: 1.6 }
  }
];

function tweenRadius(target, ms = 650) {
  const start = currentRadius;
  const t0 = performance.now();
  function step(now) {
    const u = Math.min(1, (now - t0) / ms);
    const eased = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    updateRadius(start + (target - start) * eased);
    if (u < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

window.goToStep = function goToStep(i) {
  const s = demoSteps[i] || demoSteps[0];
  document.getElementById('currentDirection').value = s.state.currentDirection;
  updateDirection(s.state.currentDirection);
  tweenRadius(s.state.distanceFromWire);
  document.getElementById('stepText').innerHTML = `<b>${s.title}.</b> ${s.narration}`;
};

document.getElementById('step0').addEventListener('click', () => window.goToStep(0));
document.getElementById('step1').addEventListener('click', () => window.goToStep(1));
document.getElementById('step2').addEventListener('click', () => window.goToStep(2));

const dragRay = new THREE.Raycaster();
const dragPointer = new THREE.Vector2();
const dragPlane = new THREE.Plane(new THREE.Vector3(1, 0, 0), -3.75);
const dragPoint = new THREE.Vector3();
let draggingMarker = false;

function setDragPointer(evt) {
  const rect = canvas.getBoundingClientRect();
  dragPointer.x = ((evt.clientX - rect.left) / rect.width) * 2 - 1;
  dragPointer.y = -((evt.clientY - rect.top) / rect.height) * 2 + 1;
}

canvas.addEventListener('pointerdown', (evt) => {
  setDragPointer(evt);
  dragRay.setFromCamera(dragPointer, camera);
  const hits = dragRay.intersectObject(markerHit, false);
  if (hits.length) {
    draggingMarker = true;
    controls.enabled = false;
    canvas.setPointerCapture?.(evt.pointerId);
  }
});

canvas.addEventListener('pointermove', (evt) => {
  if (!draggingMarker) return;
  setDragPointer(evt);
  dragRay.setFromCamera(dragPointer, camera);
  if (dragRay.ray.intersectPlane(dragPlane, dragPoint)) {
    updateRadius(dragPoint.y);
  }
});

window.addEventListener('pointerup', () => {
  if (draggingMarker) {
    draggingMarker = false;
    controls.enabled = true;
  }
});
// @FIGURE_CODE_END

