const loopArrowData = [];

function circleTube(x, r, material, tubeRadius = 0.012) {
  const pts = [];
  const n = 168;
  for (let i = 0; i <= n; i++) {
    const t = (i / n) * Math.PI * 2;
    pts.push(new THREE.Vector3(x, r * Math.cos(t), r * Math.sin(t)));
  }
  const curve = new THREE.CatmullRomCurve3(pts, true);
  return new THREE.Mesh(new THREE.TubeGeometry(curve, 168, tubeRadius, 8, true), material);
}

for (const x of loopCenters) {
