    const arrow = new THREE.Mesh(new THREE.ConeGeometry(r > 0.9 ? 0.050 : 0.039, r > 0.9 ? 0.145 : 0.112, 22), matBlue);
    arrow.position.set(x, r * Math.cos(theta), r * Math.sin(theta));
    loopGroup.add(arrow);
    loopArrowData.push({ mesh: arrow, x, r, theta });
  }
}

