}

function updateRadius(r, reveal = false) {
  currentRadius = Math.max(0.35, Math.min(2.0, Number(r)));
  updateSelectedLoop(currentRadius);

  radialLine.position.set(3.75, currentRadius / 2, 0);
  radialLine.scale.set(1, currentRadius, 1);
