const demoSteps = [
  {
    title: 'Rightward current',
    narration: 'The thumb points to the right along the wire, matching the red I arrow. The blue field arrows circulate in the same sense as the curled fingers.',
    state: { currentDirection: 'I right', distanceFromWire: 0.8, showDistance: false }
  },
  {
