    state: { currentDirection: 'I left', distanceFromWire: 0.8, showDistance: false }
  },
  {
    title: 'Move farther from the wire',
    narration: 'Drag the radial marker outward. The highlighted loop moves to a larger radius and the B readout falls, showing the field weakening with distance.',
    state: { currentDirection: 'I right', distanceFromWire: 1.6, showDistance: true }
  }
];

function tweenRadius(target, ms = 650, reveal = false) {
  const start = currentRadius;
  const t0 = performance.now();
  if (reveal) setDistanceVisibility(true);
  function step(now) {
    const u = Math.min(1, (now - t0) / ms);
    const eased = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    updateRadius(start + (target - start) * eased, reveal);
    if (u < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

window.goToStep = function goToStep(i) {
  const s = demoSteps[i] || demoSteps[0];
  document.getElementById('currentDirection').value = s.state.currentDirection;
  updateDirection(s.state.currentDirection);
  setDistanceVisibility(!!s.state.showDistance);
  tweenRadius(s.state.distanceFromWire, 650, !!s.state.showDistance);
  document.getElementById('stepText').innerHTML = `<b>${s.title}.</b> ${s.narration}`;
};

