const dragPlane = new THREE.Plane(new THREE.Vector3(1, 0, 0), -3.75);
const dragPoint = new THREE.Vector3();
let draggingMarker = false;

function setDragPointer(evt) {
  const rect = canvas.getBoundingClientRect();
  dragPointer.x = ((evt.clientX - rect.left) / rect.width) * 2 - 1;
  dragPointer.y = -((evt.clientY - rect.top) / rect.height) * 2 + 1;
}

canvas.addEventListener('pointerdown', (evt) => {
  if (!distanceVisible) return;
  setDragPointer(evt);
  dragRay.setFromCamera(dragPointer, camera);
  const hits = dragRay.intersectObject(markerHit, false);
  if (hits.length) {
    draggingMarker = true;
    controls.enabled = false;
    canvas.setPointerCapture?.(evt.pointerId);
  }
});

canvas.addEventListener('pointermove', (evt) => {
  if (!draggingMarker) return;
  setDragPointer(evt);
  dragRay.setFromCamera(dragPointer, camera);
  if (dragRay.ray.intersectPlane(dragPlane, dragPoint)) {
    updateRadius(dragPoint.y, true);
  }
});

